package com.fiap.sast.rules;
import com.fiap.sast.analysis.SecurityFinding; import com.github.javaparser.ast.CompilationUnit; import com.github.javaparser.ast.body.VariableDeclarator; import com.github.javaparser.ast.expr.MethodCallExpr; import org.springframework.stereotype.Component; import java.util.*;
@Component public class DeserializationRule implements SecurityRule { public String ruleId(){return "SAST-JAVA-003";} public List<SecurityFinding> analyze(CompilationUnit a,String s,String file){var names=new HashSet<String>();a.findAll(VariableDeclarator.class).forEach(v->{if(v.getTypeAsString().endsWith("ObjectInputStream"))names.add(v.getNameAsString());});var out=new ArrayList<SecurityFinding>();a.findAll(MethodCallExpr.class).forEach(m->{if(m.getNameAsString().equals("readObject")&&m.getScope().map(x->names.contains(x.toString())).orElse(false))out.add(RuleSupport.finding(ruleId(),"Desserialização potencialmente insegura","High","CWE-502","Uso de ObjectInputStream.readObject().",file,s,m));});return out;} }
